1	import { NextResponse } from "next/server";
2	import { realUser } from "@/lib/auth";
3	import { canAccess } from "@/lib/rbac";
4	import { db } from "@/lib/db";
5	import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
6	
7	export const runtime = "nodejs";
8	export const dynamic = "force-dynamic";
9	
10	/**
11	 * READ-ONLY unread live-chat count for the admin browser notifier.
12	 *
13	 * GET /api/admin/chat-unread → { count } — the number of chat conversations
14	 * flagged `unreadForAgent` (the same "needs a reply" signal the chat inbox and
15	 * the sidebar badge count by). <AdminChatNotifier/> polls this while an admin
16	 * tab is open and beeps / fires a Web Notification when the count increases.
17	 *
18	 * Gated to support staff exactly like the inbox itself; never writes anything.
19	 */
20	export async function GET() {
21	  const user = await realUser();
22	  if (!user || !canAccess(user.role, "support")) {
23	    return NextResponse.json({ error: "unauthorized" }, { status: 401, headers: NO_STORE_HEADERS });
24	  }
25	
26	  // Fail soft to 0 so a transient DB hiccup never surfaces as a notifier error.
27	  const count = await db.chatConversation
28	    .count({ where: { unreadForAgent: true } })
29	    .catch(() => 0);
30	
31	  return NextResponse.json({ count }, { headers: NO_STORE_HEADERS });
32	}
