1	import { NextResponse } from "next/server";
2	import { realUser } from "@/lib/auth";
3	import { canAccess } from "@/lib/rbac";
4	import { hasAreaAccess } from "@/lib/staff-grants";
5	import { listFolders } from "@/lib/actions-mail";
6	import { listCompanyMailboxes } from "@/lib/actions-company-mail";
7	import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
8	
9	export const runtime = "nodejs";
10	export const dynamic = "force-dynamic";
11	
12	/**
13	 * READ-ONLY unread-mail count for the admin floating email indicator.
14	 *
15	 * GET /api/admin/inbox-unread → { unread } — the combined unread INBOX count
16	 * across every company mailbox this account can actually read (ADMIN/SUPPORT/
17	 * BILLING: all of them; EMPLOYEE: their own plus whatever else was granted —
18	 * `listCompanyMailboxes` scopes this itself, see lib/staff-mailbox-access.ts).
19	 * Mirrors the customer /api/mail/unread route: IMAP is far too slow to sit in
20	 * a server layout render, so <AdminIndicators/> polls this from the browser
21	 * and animates the bubble when the count increases.
22	 *
23	 * Gate is an OR of `canAccess(role, "platform")` (unchanged — ADMIN's
24	 * original access) or `hasAreaAccess(user, "companyInbox")` for the EMPLOYEE
25	 * grant. Confirmed live 2026-09-03 this 401'd for every EMPLOYEE regardless
26	 * of grants, same root cause as support-unread's fix — canAccess alone never
27	 * recognizes a StaffGrant. Fails SOFT to 0 per mailbox and overall so a
28	 * mailbox hiccup / IMAP outage never surfaces as a widget error. Never
29	 * writes anything.
30	 */
31	export async function GET() {
32	  const user = await realUser();
33	  if (!user || !(canAccess(user.role, "platform") || (await hasAreaAccess(user, "companyInbox")))) {
34	    return NextResponse.json({ unread: 0 }, { status: 401, headers: NO_STORE_HEADERS });
35	  }
36	
37	  try {
38	    const boxes = await listCompanyMailboxes();
39	    // Cap the fan-out: each mailbox is one IMAP connection. A handful of company
40	    // mailboxes is the norm; never open more than a few per poll.
41	    const targets = boxes.slice(0, 6);
42	    const counts = await Promise.all(
43	      targets.map(async (b) => {
44	        try {
45	          const folders = await listFolders(b.address);
46	          const inbox = folders.find((f) => f.role === "inbox");
47	          return inbox?.unread ?? 0;
48	        } catch {
49	          return 0; // this mailbox failed — count it as 0, don't fail the whole poll
50	        }
51	      }),
52	    );
53	    const unread = counts.reduce((sum, n) => sum + n, 0);
54	    return NextResponse.json({ unread }, { headers: NO_STORE_HEADERS });
55	  } catch {
56	    return NextResponse.json({ unread: 0 }, { headers: NO_STORE_HEADERS });
57	  }
58	}
