1	import { NextResponse } from "next/server";
2	import { realUser } from "@/lib/auth";
3	import { canAccess } from "@/lib/rbac";
4	import { hasAnyAreaAccess } from "@/lib/staff-grants";
5	import { db } from "@/lib/db";
6	import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
7	
8	export const runtime = "nodejs";
9	export const dynamic = "force-dynamic";
10	
11	/**
12	 * READ-ONLY support-attention counts for the admin floating support indicator.
13	 *
14	 * GET /api/admin/support-unread → { tickets, chat } —
15	 *   - `tickets`: tickets awaiting a staff reply (OPEN + CUSTOMER_REPLY), the same
16	 *     signal as the "Awaiting staff" stat on /admin/support and the sidebar badge.
17	 *   - `chat`: live-chat conversations flagged `unreadForAgent` (mirrors the
18	 *     existing /api/admin/chat-unread source and the chat inbox badge).
19	 *
20	 * <AdminIndicators/> polls this on both the admin AND staff portals while a
21	 * tab is open, and animates the bubble (bell shake + pulse) when the combined
22	 * count increases. Never writes anything, and each count fails soft to 0 so
23	 * a transient DB hiccup can't surface as a widget error.
24	 *
25	 * Gate is an OR of two independent checks: `canAccess(role, "support")`
26	 * (unchanged — SUPPORT/ADMIN's original role-based access) or
27	 * `hasAnyAreaAccess` against the newer supportTickets/liveChat grants an
28	 * EMPLOYEE can hold. Confirmed live 2026-09-03 this route 401'd for every
29	 * EMPLOYEE regardless of grants — canAccess alone never recognizes them,
30	 * since the whole point of StaffGrant is reaching these two areas WITHOUT
31	 * being in the "support" role-based area. The indicator looked broken; it
32	 * just never checked the right thing.
33	 */
34	export async function GET() {
35	  const user = await realUser();
36	  if (!user || !(canAccess(user.role, "support") || (await hasAnyAreaAccess(user, ["supportTickets", "liveChat"])))) {
37	    return NextResponse.json({ error: "unauthorized" }, { status: 401, headers: NO_STORE_HEADERS });
38	  }
39	
40	  const [tickets, chat] = await Promise.all([
41	    db.ticket
42	      .count({ where: { status: { in: ["OPEN", "CUSTOMER_REPLY"] } } })
43	      .catch(() => 0),
44	    db.chatConversation.count({ where: { unreadForAgent: true } }).catch(() => 0),
45	  ]);
46	
47	  return NextResponse.json({ tickets, chat }, { headers: NO_STORE_HEADERS });
48	}
