1	import { NextResponse } from "next/server";
2	import { realUser } from "@/lib/auth";
3	import { canAccess } from "@/lib/rbac";
4	import { getMonitorFeed } from "@/lib/monitor-feed";
5	import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
6	
7	export const runtime = "nodejs";
8	export const dynamic = "force-dynamic";
9	
10	/**
11	 * GET /api/admin/monitor-feed → the live-ops feed for /admin/monitor.
12	 *
13	 * Polled client-side by <LiveMonitorTerminal/> to drive the console view
14	 * without a full page navigation. Read-only, `fleet`-gated (ADMIN only, same
15	 * as every other fleet page) exactly like the SSR page it backs — a hand-typed
16	 * fetch from a non-admin session gets a 401, not a data leak.
17	 */
18	export async function GET() {
19	  const user = await realUser();
20	  if (!user || !canAccess(user.role, "fleet")) {
21	    return NextResponse.json({ error: "unauthorized" }, { status: 401, headers: NO_STORE_HEADERS });
22	  }
23	
24	  try {
25	    const feed = await getMonitorFeed();
26	    return NextResponse.json(feed, { headers: NO_STORE_HEADERS });
27	  } catch (e) {
28	    console.error("[monitor-feed] route error", e);
29	    return NextResponse.json({ error: "feed unavailable" }, { status: 500, headers: NO_STORE_HEADERS });
30	  }
31	}
