1	import { NextRequest, NextResponse } from "next/server";
2	import { realUser } from "@/lib/auth";
3	import { canAccess } from "@/lib/rbac";
4	import { db } from "@/lib/db";
5	import type { InvoiceStatus, Prisma } from "@prisma/client";
6	import { formatInvoiceNumber, invoiceBranding } from "@/lib/invoices";
7	
8	/**
9	 * RBAC-checked CSV export of the current (filtered) admin table.
10	 *
11	 *   /api/admin/export?type=users&q=…
12	 *   /api/admin/export?type=invoices&status=OPEN
13	 *
14	 * The filter params mirror the corresponding admin page so "Export CSV" always
15	 * reflects what the operator is looking at. Exports the full filtered set (not
16	 * just the current page). Never cached.
17	 */
18	export const dynamic = "force-dynamic";
19	
20	function csvCell(v: unknown): string {
21	  const s = v == null ? "" : String(v);
22	  return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
23	}
24	
25	function toCsv(headers: string[], rows: (string | number | null | undefined)[][]): string {
26	  const lines = [headers.map(csvCell).join(",")];
27	  for (const row of rows) lines.push(row.map(csvCell).join(","));
28	  return lines.join("\r\n");
29	}
30	
31	function money(cents: number): string {
32	  return (cents / 100).toFixed(2);
33	}
34	
35	const INVOICE_STATUSES: InvoiceStatus[] = ["OPEN", "PAID", "VOID", "REFUNDED"];
36	
37	export async function GET(req: NextRequest) {
38	  const user = await realUser();
39	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
40	
41	  const sp = req.nextUrl.searchParams;
42	  const type = sp.get("type");
43	  const stamp = new Date().toISOString().slice(0, 10);
44	
45	  if (type === "users") {
46	    if (!canAccess(user.role, "clients")) {
47	      return NextResponse.json({ error: "forbidden" }, { status: 403 });
48	    }
49	    const query = (sp.get("q") ?? "").trim();
50	    const where: Prisma.UserWhereInput = query
51	      ? {
52	          OR: [
53	            { email: { contains: query, mode: "insensitive" } },
54	            { name: { contains: query, mode: "insensitive" } },
55	          ],
56	        }
57	      : {};
58	
59	    const users = await db.user.findMany({
60	      where,
61	      include: {
62	        servers: {
63	          where: { status: { notIn: ["DELETING"] } },
64	          select: { isFree: true, plan: { select: { priceCents: true } } },
65	        },
66	      },
67	      orderBy: { createdAt: "desc" },
68	    });
69	
70	    const csv = toCsv(
71	      ["id", "name", "email", "role", "balance_usd", "mrr_usd", "servers", "suspended", "joined"],
72	      users.map((u) => {
73	        const mrr = u.servers.reduce((n, s) => n + (s.isFree ? 0 : s.plan.priceCents), 0);
74	        return [
75	          u.id,
76	          u.name,
77	          u.email,
78	          u.role,
79	          money(u.balanceCents),
80	          money(mrr),
81	          u.servers.length,
82	          u.suspended ? "yes" : "no",
83	          u.createdAt.toISOString(),
84	        ];
85	      })
86	    );
87	
88	    return new NextResponse(csv, {
89	      status: 200,
90	      headers: {
91	        "Content-Type": "text/csv; charset=utf-8",
92	        "Content-Disposition": `attachment; filename="nxeon-clients-${stamp}.csv"`,
93	        "Cache-Control": "private, no-store",
94	      },
95	    });
96	  }
97	
98	  if (type === "invoices") {
99	    if (!canAccess(user.role, "billing")) {
100	      return NextResponse.json({ error: "forbidden" }, { status: 403 });
101	    }
102	    const statusParam = sp.get("status");
103	    const status = INVOICE_STATUSES.includes(statusParam as InvoiceStatus)
104	      ? (statusParam as InvoiceStatus)
105	      : undefined;
106	
107	    const invoices = await db.invoice.findMany({
108	      where: status ? { status } : {},
109	      include: { user: { select: { email: true, name: true } } },
110	      orderBy: { createdAt: "desc" },
111	    });
112	    const invoiceNumberPrefix = (await invoiceBranding()).numberPrefix;
113	
114	    const csv = toCsv(
115	      ["number", "client_name", "client_email", "status", "description", "amount_usd", "tax_usd", "issued", "paid_at"],
116	      invoices.map((inv) => [
117	        // The SAME identifier the customer sees. A CSV used for accounting or to
118	        // answer a support query has to reconcile against the number they quote.
119	        formatInvoiceNumber(inv.number, invoiceNumberPrefix),
120	        inv.user.name,
121	        inv.user.email,
122	        inv.status,
123	        inv.description,
124	        money(inv.amountCents),
125	        money(inv.taxCents),
