9	// NOT appUrl()/APP_URL — see connect/route.ts for why: the admin portal only
10	// resolves on the secret admin subdomain, never the public domain.
11	const base = () => (process.env.NXEON_ADMIN_ORIGIN ?? "https://nxeon.cloud").replace(/\/$/, "");
12	const SETTINGS_PATH = "/admin/seo/settings";
13	
14	/** Clear the one-shot OAuth state cookie on every exit path. */
15	function finish(res: NextResponse): NextResponse {
16	  res.cookies.set({
17	    name: "nx_gsc_oauth_state",
18	    value: "",
19	    httpOnly: true,
20	    path: "/api/admin/integrations/google-search-console",
21	    maxAge: 0,
22	  });
23	  return res;
