26	/**
27	 * Step 2 of "Connect Google Search Console": the OAuth redirect target.
28	 *
29	 * Verifies the CSRF `state` against the httpOnly cookie, exchanges the code
30	 * for tokens, encrypts + stores the refresh token (+ connected account email,
31	 * + the resolved verified siteUrl) in `GscConnection`, then redirects back to
32	 * the admin settings page with a success/error indicator in the query string.
33	 * No token is ever logged or put in a URL.
34	 */
35	export async function GET(req: NextRequest) {
36	  const user = await realUser();
37	  if (!user || !canAccess(user.role, "platform")) {
38	    return finish(NextResponse.redirect(`${base()}/admin`));
39	  }
40	
41	  const fail = (msg: string) =>
42	    finish(
43	      NextResponse.redirect(
44	        `${base()}${SETTINGS_PATH}?gsc=error&gscmsg=${encodeURIComponent(msg)}`,
45	      ),
46	    );
47	
48	  const sp = req.nextUrl.searchParams;
49	
50	  const oauthError = sp.get("error");
51	  if (oauthError) {
52	    return fail(
53	      oauthError === "access_denied"
54	        ? "Google Search Console connection cancelled."
55	        : `Google returned an error (${oauthError.slice(0, 60)}).`,
56	    );
57	  }
58	
59	  const state = sp.get("state") ?? "";
60	  const stashedState = req.cookies.get("nx_gsc_oauth_state")?.value ?? "";
61	  if (!stashedState || !state || state !== stashedState) {
62	    return fail("That Google sign-in link expired or didn't match. Please try connecting again.");
63	  }
64	
65	  const code = sp.get("code") ?? "";
66	  if (!code) return fail("Google didn't return an authorization code. Please try connecting again.");
67	
68	  const exchanged = await gscExchangeCode(code);
69	  if (!exchanged.accessToken) {
70	    return fail(exchanged.error ?? "Couldn't complete the Google Search Console connection. Please try again.");
71	  }
72	  if (!exchanged.refreshToken) {
73	    // access_type=offline + prompt=consent should always yield one; if Google
74	    // withholds it (e.g. a prior grant wasn't revoked first) we cannot refresh
75	    // later, so fail loudly rather than silently storing a connection that
76	    // will die the moment the short-lived access token expires.
77	    return fail(
78	      "Google didn't return a refresh token. Revoke Nxeon's access at https://myaccount.google.com/permissions and try connecting again.",
79	    );
80	  }
81	
82	  await storeGscConnection({ refreshToken: exchanged.refreshToken, accessToken: exchanged.accessToken });
83	  await db.auditLog
84	    .create({ data: { userId: user.id, action: "gsc.connect", detail: "OAuth authorised" } })
85	    .catch(() => {});
86	
87	  return finish(NextResponse.redirect(`${base()}${SETTINGS_PATH}?gsc=connected`));
88	}
