1	import { NextResponse } from "next/server";
2	import { db } from "@/lib/db";
3	import { requireUser } from "@/lib/auth";
4	import { checkRateLimit } from "@/lib/rate-limit";
5	import { validateImageBytes, MAX_ATTACHMENT_BYTES } from "@/lib/chat-attachment";
6	import { appUrl } from "@/lib/email-render";
7	import { trustedClientIp } from "@/app/api/_lib/client-ip";
8	
9	export const runtime = "nodejs";
10	
11	/**
12	 * Image upload for the webmail SIGNATURE editor.
13	 *
14	 * POST /api/mail/signature-image  (multipart/form-data: file) — the signed-in
15	 * mailbox owner picks an image from their computer; we validate its real bytes
16	 * (signature sniff rejects SVG/non-images, cap 5 MB), store the bytes in
17	 * Postgres under the user's id, and return an ABSOLUTE https URL:
18	 *
19	 *   { url: "https://nxeon.cloud/api/mail/signature-image/<cuid>" }
20	 *
21	 * The editor inserts that URL as an <img src>. It is absolute (not a relative
22	 * "/api/…" path) so the image also loads in the RECIPIENT'S external mail
23	 * client, which has no notion of our origin. We host rather than inline because
24	 * `safeHtml` strips `data:` URLs and email clients block inline data images.
25	 *
26	 * Only authenticated owners may upload (requireUser). Per-user + per-IP rate
27	 * limited. To keep storage bounded we cap the number of images per user and
28	 * prune the oldest when over the cap.
29	 */
30	
31	const MAX_IMAGES_PER_USER = 20;
32	
33	export async function POST(req: Request) {
34	  let user;
35	  try {
36	    user = await requireUser();
37	  } catch {
38	    return NextResponse.json({ error: "You must be signed in to upload an image." }, { status: 401 });
39	  }
40	
41	  // Keyed on the user id ALONE. It used to be `${user.id}:${clientIp}`, where
42	  // the IP half came from the caller-supplied first hop of X-Forwarded-For —
43	  // so one account could mint a fresh 15/min bucket per forged header and push
44	  // unbounded 5 MB blobs into Postgres. The account is the thing being limited.
45	  const rl = checkRateLimit(`sig-image:${user.id}`, { max: 15, windowMs: 60_000 });
46	  if (!rl.ok) {
47	    return NextResponse.json(
48	      { error: "Too many uploads. Please slow down." },
49	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } },
50	    );
51	  }
52	
53	  let form: FormData;
54	  try {
55	    form = await req.formData();
56	  } catch {
57	    return NextResponse.json({ error: "Invalid upload." }, { status: 400 });
58	  }
59	
60	  const file = form.get("file");
61	  if (!(file instanceof File)) {
62	    return NextResponse.json({ error: "No image provided." }, { status: 400 });
63	  }
64	  // Cheap guard before buffering the whole body into memory.
65	  if (file.size > MAX_ATTACHMENT_BYTES) {
66	    return NextResponse.json({ error: "Image is larger than 5 MB." }, { status: 413 });
67	  }
68	
69	  const bytes = Buffer.from(await file.arrayBuffer());
70	  const check = validateImageBytes(bytes, file.type);
71	  if (!check.ok) return NextResponse.json({ error: check.error }, { status: 400 });
72	
73	  const created = await db.signatureImage.create({
74	    data: {
75	      userId: user.id,
76	      mime: check.mime,
77	      sizeBytes: check.bytes.length,
78	      data: new Uint8Array(check.bytes),
79	    },
80	    select: { id: true },
81	  });
82	
83	  // Keep storage bounded: prune the user's oldest images beyond the cap.
84	  try {
85	    const old = await db.signatureImage.findMany({
86	      where: { userId: user.id },
87	      orderBy: { createdAt: "desc" },
88	      skip: MAX_IMAGES_PER_USER,
89	      select: { id: true },
90	    });
91	    if (old.length > 0) {
92	      await db.signatureImage.deleteMany({ where: { id: { in: old.map((r) => r.id) } } });
93	    }
94	  } catch {
95	    /* pruning is best-effort — never fail the upload over it */
96	  }
97	
98	  return NextResponse.json({ url: `${appUrl()}/api/mail/signature-image/${created.id}` });
99	}
