10	/** Stream a work-task attachment. Gated on the "tasks" grant (same authority
11	 *  as every action in lib/actions-work.ts) — mirrors
12	 *  app/api/board/attachments/[id]/route.ts's serving logic, re-gated for this
13	 *  separate, EMPLOYEE-reachable system. Supports Range so video seeks work. */
14	export async function GET(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
15	  try {
16	    await requireGrant("tasks");
17	  } catch {
18	    return new NextResponse("Forbidden", { status: 403 });
19	  }
20	  const { id } = await params;
21	  const att = await db.workTaskAttachment.findUnique({ where: { id } });
22	  if (!att) return new NextResponse("Not found", { status: 404 });
23	  const path = join(WORK_UPLOAD_DIR, att.taskId, att.storedName);
24	  let size: number;
25	  try {
26	    size = (await fs.stat(path)).size;
27	  } catch {
28	    return new NextResponse("Missing", { status: 404 });
29	  }
30	
31	  const range = req.headers.get("range");
32	  const disposition = att.kind === "FILE" ? `attachment; filename="${att.filename.replace(/"/g, "")}"` : "inline";
33	  // Never let an inline-served attachment execute as a document: `nosniff` stops
34	  // MIME-sniffing an image into HTML, and `default-src 'none'; sandbox` neuters
35	  // any script even in a legacy SVG that predates the upload-side reject.
36	  const baseHeaders: Record<string, string> = {
37	    "Content-Type": att.mime,
38	    "Content-Disposition": disposition,
39	    "Accept-Ranges": "bytes",
40	    "X-Content-Type-Options": "nosniff",
41	    "Content-Security-Policy": "default-src 'none'; sandbox",
42	  };
43	
44	  if (range) {
45	    const m = /bytes=(\d+)-(\d*)/.exec(range);
46	    if (m) {
47	      const start = Number(m[1]);
48	      const end = m[2] ? Math.min(Number(m[2]), size - 1) : size - 1;
49	      if (start <= end && start < size) {
50	        const stream = createReadStream(path, { start, end });
51	        return new NextResponse(Readable.toWeb(stream) as unknown as ReadableStream, {
52	          status: 206,
53	          headers: { ...baseHeaders, "Content-Range": `bytes ${start}-${end}/${size}`, "Content-Length": String(end - start + 1) },
54	        });
55	      }
56	    }
57	  }
58	  const stream = createReadStream(path);
59	  return new NextResponse(Readable.toWeb(stream) as unknown as ReadableStream, {
60	    status: 200,
61	    headers: { ...baseHeaders, "Content-Length": String(size) },
62	  });
63	}
