1	import { NextResponse } from "next/server";
2	import { db } from "@/lib/db";
3	import { currentUser } from "@/lib/auth";
4	import { checkRateLimit } from "@/lib/rate-limit";
5	import { trustedClientIp } from "@/app/api/_lib/client-ip";
6	import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
7	import { readTyping } from "@/lib/chat-typing";
8	import { readBotStep } from "@/lib/chat-bot-step";
9	import { mirrorChatMessageToDiscord } from "@/lib/discord-bridge";
10	
11	export const runtime = "nodejs";
12	
13	/**
14	 * Public live-chat endpoint used by <ChatWidget/>.
15	 *
16	 * POST /api/chat  — start or continue a conversation for a visitorId.
17	 * GET  /api/chat?visitorId=…  — poll the visitor's open conversation.
18	 *
19	 * Everything is scoped strictly by the client-supplied `visitorId`; we never
20	 * return another visitor's data. Signed-in customers additionally get their
21	 * `userId` stamped on the conversation. Unauthenticated + write-heavy, so the
22	 * POST path is rate-limited per IP.
23	 */
24	
25	function clip(v: unknown, max: number): string | null {
26	  return typeof v === "string" && v.trim() ? v.trim().slice(0, max) : null;
27	}
28	
29	type AttachmentRow = { id: string; mime: string; sizeBytes: number } | null;
30	
31	function serialize(convo: {
32	  id: string;
33	  status: string;
34	  name: string | null;
35	  email: string | null;
36	  messages: {
37	    id: string;
38	    sender: string;
39	    body: string;
40	    cardsJson?: string | null;
41	    createdAt: Date;
42	    attachment?: AttachmentRow;
43	  }[];
44	}) {
45	  return {
46	    conversation: {
47	      id: convo.id,
48	      status: convo.status,
49	      name: convo.name,
50	      email: convo.email,
51	    },
52	    messages: convo.messages.map((m) => {
53	      let cards: unknown = null;
54	      if (m.cardsJson) {
55	        try {
56	          cards = JSON.parse(m.cardsJson);
57	        } catch {
58	          cards = null;
59	        }
60	      }
61	      return {
62	        id: m.id,
63	        sender: m.sender,
64	        body: m.body,
65	        createdAt: m.createdAt.toISOString(),
66	        cards,
67	        attachment: m.attachment
68	          ? { id: m.attachment.id, mime: m.attachment.mime, sizeBytes: m.attachment.sizeBytes }
69	          : null,
70	      };
71	    }),
72	  };
73	}
74	
75	export async function POST(req: Request) {
76	  const rl = checkRateLimit(`chat:${trustedClientIp(req)}`, { max: 30, windowMs: 60_000 });
77	  if (!rl.ok) {
78	    return NextResponse.json(
79	      { error: "Too many messages. Please slow down." },
80	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
81	    );
82	  }
83	
84	  const raw = (await req.json().catch(() => ({}))) as Record<string, unknown>;
85	  const visitorId = clip(raw.visitorId, 100);
86	  const conversationId = clip(raw.conversationId, 40);
87	  const body = clip(raw.body, 5000);
88	  const name = clip(raw.name, 120);
89	  const email = clip(raw.email, 200);
90	
91	  if (!visitorId) return NextResponse.json({ error: "Missing visitorId." }, { status: 400 });
92	  if (!body) return NextResponse.json({ error: "Message cannot be empty." }, { status: 400 });
93	
94	  const user = await currentUser();
95	  const ownedBy = [{ visitorId } as Record<string, unknown>].concat(
96	    user?.id ? [{ userId: user.id }] : [],
97	  );
98	
99	  // If the client names a conversation it owns, continue it (resuming past
100	  // history, reopening if it was closed). Otherwise start a brand-new one — we
101	  // no longer auto-resume the latest, so returning gives a fresh chat while old
102	  // threads stay available in the history list.
103	  let convo = conversationId
104	    ? await db.chatConversation.findFirst({
105	        where: { id: conversationId, OR: ownedBy },
106	        select: { id: true, name: true, email: true },
107	      })
108	    : null;
109	
110	  if (!convo) {
111	    // Anonymous (not signed in) visitors must give a name + valid email before
112	    // starting. Signed-in customers already have both, so they're never asked.
113	    if (!user) {
114	      const nm = name ?? null;
115	      const em = email ?? null;
116	      if (!nm || !em || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(em)) {
117	        return NextResponse.json(
118	          { error: "Please add your name and a valid email to start the chat.", needIdentity: true },
119	          { status: 400 },
120	        );
121	      }
122	    }
123	    convo = await db.chatConversation.create({
124	      data: {
125	        visitorId,
126	        userId: user?.id ?? null,
127	        name: name ?? user?.name ?? null,
128	        email: email ?? user?.email ?? null,
129	      },
130	      select: { id: true, name: true, email: true },
131	    });
132	  }
133	
134	  await db.$transaction([
135	    db.chatMessage.create({
136	      data: { conversationId: convo.id, sender: "visitor", body },
137	    }),
138	    db.chatConversation.update({
139	      where: { id: convo.id },
140	      data: {
141	        status: "OPEN", // reopen if the visitor is resuming a closed thread
142	        unreadForAgent: true,
143	        lastMessageAt: new Date(),
144	        // Backfill identity / link account if it arrives after creation.
145	        ...(user?.id ? { userId: user.id } : {}),
146	        ...(name && !convo.name ? { name } : {}),
147	        ...(email && !convo.email ? { email } : {}),
148	      },
149	    }),
150	  ]);
151	
152	  // Discord bridge (Phase 1 mirror): best-effort, never blocks the visitor's
153	  // message — creates the guild channel on the visitor's FIRST message, posts
154	  // into the existing channel on every message after — see
155	  // lib/discord-bridge.ts's mirrorChatMessageToDiscord.
156	  await mirrorChatMessageToDiscord(convo.id, body, "visitor");
157	
158	  // AI assistant + human-handoff orchestration (see lib/kb-run.ts). Best-effort
159	  // and fully wrapped: it must NEVER break live chat, and it stays silent once a
160	  // human has engaged.
161	  try {
162	    const { runAssistant } = await import("@/lib/kb-run");
163	    await runAssistant({ conversationId: convo.id, visitorId, currentBody: body });
164	  } catch {
165	    /* assistant is non-essential — never fail the visitor's message on it */
166	  }
167	
168	  const full = await db.chatConversation.findUnique({
169	    where: { id: convo.id },
170	    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
171	  });
172	  return NextResponse.json(serialize(full!), { headers: NO_STORE_HEADERS });
173	}
174	
175	export async function GET(req: Request) {
176	  const url = new URL(req.url);
177	  const visitorId = clip(url.searchParams.get("visitorId"), 100);
178	  const conversationId = clip(url.searchParams.get("conversationId"), 40);
179	  if (!visitorId) {
180	    return NextResponse.json({ conversation: null, messages: [] }, { headers: NO_STORE_HEADERS });
181	  }
182	
183	  const user = await currentUser();
184	  const ownedBy = [{ visitorId } as Record<string, unknown>].concat(
185	    user?.id ? [{ userId: user.id }] : [],
186	  );
187	
188	  // Poll a specific conversation when named (scoped to the visitor/user), else
189	  // the most recent open thread for back-compat.
190	  let convo = conversationId
191	    ? await db.chatConversation.findFirst({
192	        where: { id: conversationId, OR: ownedBy },
193	        include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
194	      })
195	    : await db.chatConversation.findFirst({
196	        where: { visitorId, status: "OPEN" },
197	        orderBy: { lastMessageAt: "desc" },
198	        include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
199	      });
200	
201	  if (!convo) {
202	    return NextResponse.json({ conversation: null, messages: [] }, { headers: NO_STORE_HEADERS });
203	  }
204	
205	  // If the bot is waiting on a live agent, let the poll drive the handoff window:
206	  // post the "no agents available" fallback once it elapses, then refresh so the
207	  // visitor sees it on this same poll rather than the next one.
208	  if (convo.botEscalatedAt) {
209	    try {
210	      const { checkEscalationTimeout } = await import("@/lib/kb-run");
211	      await checkEscalationTimeout(convo.id);
212	      const refreshed = await db.chatConversation.findFirst({
213	        where: { id: convo.id },
214	        include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
215	      });
216	      if (refreshed) convo = refreshed;
217	    } catch {
218	      /* non-essential */
219	    }
220	  }
221	
222	  // Reading the thread clears the visitor-facing unread flag.
223	  if (convo.unreadForUser) {
224	    await db.chatConversation
225	      .update({ where: { id: convo.id }, data: { unreadForUser: false } })
226	      .catch(() => {});
227	  }
228	
229	  // The whole support transcript, plus the name/email the visitor gave. The
230	  // `?visitorId=` in the URL is the ONLY thing scoping it, which makes the URL
231	  // itself the secret — precisely the shape a shared cache must never store.
232	  //
233	  // `typing.agent` tells the widget whether a support agent is composing a reply
234	  // right now; it self-expires, so a stale poll can only ever under-report.
235	  // `botStep` is the AI agent's current live "thinking" step (e.g. "Checking
236	  // your billing…"), sourced from lib/chat-bot-step.ts; it self-expires too, so
237	  // a stalled/crashed model call can never leave a stuck label on screen.
238	  return NextResponse.json(
239	    { ...serialize(convo), typing: { agent: readTyping(convo.id).agent }, botStep: readBotStep(convo.id) },
240	    { headers: NO_STORE_HEADERS },
241	  );
242	}
