7	/**
8	 * GET /api/chat/[id]?visitorId=…  — fetch a single conversation the widget
9	 * already knows the id of. Strictly scoped: the row is only returned when its
10	 * `visitorId` matches the one supplied, so a visitor can never read another's
11	 * thread by guessing an id. Reading clears the visitor-facing unread flag.
12	 */
13	
14	function clip(v: unknown, max: number): string | null {
15	  return typeof v === "string" && v.trim() ? v.trim().slice(0, max) : null;
16	}
17	
18	export async function GET(
19	  req: Request,
20	  { params }: { params: Promise<{ id: string }> }
21	) {
22	  const { id } = await params;
23	  const url = new URL(req.url);
24	  const visitorId = clip(url.searchParams.get("visitorId"), 100);
25	
26	  if (!id || !visitorId) {
27	    return NextResponse.json({ conversation: null, messages: [] }, { headers: NO_STORE_HEADERS });
28	  }
29	
30	  const convo = await db.chatConversation.findFirst({
31	    where: { id, visitorId },
32	    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
33	  });
34	
35	  if (!convo) {
36	    return NextResponse.json({ conversation: null, messages: [] }, { headers: NO_STORE_HEADERS });
37	  }
38	
39	  if (convo.unreadForUser) {
40	    await db.chatConversation
41	      .update({ where: { id: convo.id }, data: { unreadForUser: false } })
42	      .catch(() => {});
43	  }
44	
45	  return NextResponse.json(
46	    {
47	      conversation: {
48	        id: convo.id,
49	        status: convo.status,
50	        name: convo.name,
51	        email: convo.email,
52	      },
53	      messages: convo.messages.map((m) => ({
54	        id: m.id,
55	        sender: m.sender,
56	        body: m.body,
57	        createdAt: m.createdAt.toISOString(),
58	        attachment: m.attachment
59	          ? { id: m.attachment.id, mime: m.attachment.mime, sizeBytes: m.attachment.sizeBytes }
60	          : null,
61	      })),
62	    },
63	    { headers: NO_STORE_HEADERS },
64	  );
65	}
