1	import { NextResponse } from "next/server";
2	import { db } from "@/lib/db";
3	import { currentUser } from "@/lib/auth";
4	import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
5	
6	export const runtime = "nodejs";
7	
8	/**
9	 * GET /api/chat/list?visitorId=… — the visitor's past conversations, newest
10	 * first, so the widget can show a "previous chats" list they can resume.
11	 *
12	 * Ownership: a conversation is theirs if the `visitorId` matches, OR (when
13	 * signed in) the conversation's `userId` matches the current user — so a
14	 * logged-in customer sees their threads across browsers/devices, plus any
15	 * anonymous chats started in this browser before they logged in.
16	 */
17	
18	function clip(v: unknown, max: number): string | null {
19	  return typeof v === "string" && v.trim() ? v.trim().slice(0, max) : null;
20	}
21	
22	export async function GET(req: Request) {
23	  const url = new URL(req.url);
24	  const visitorId = clip(url.searchParams.get("visitorId"), 100);
25	  const user = await currentUser();
26	
27	  if (!visitorId && !user) {
28	    return NextResponse.json({ conversations: [] }, { headers: NO_STORE_HEADERS });
29	  }
30	
31	  const or: Array<Record<string, unknown>> = [];
32	  if (visitorId) or.push({ visitorId });
33	  if (user?.id) or.push({ userId: user.id });
34	
35	  const rows = await db.chatConversation.findMany({
36	    where: { OR: or },
37	    orderBy: { lastMessageAt: "desc" },
38	    take: 20,
39	    select: {
40	      id: true,
41	      status: true,
42	      lastMessageAt: true,
43	      unreadForUser: true,
44	      // First message → a human-readable title; last message → a preview line.
45	      messages: {
46	        orderBy: { createdAt: "asc" },
47	        take: 1,
48	        select: { body: true },
49	      },
50	    },
51	  });
52	
53	  // Last message per conversation for the preview (cheap: one grouped query).
54	  const ids = rows.map((r) => r.id);
55	  const lasts = ids.length
56	    ? await db.chatMessage.findMany({
57	        where: { conversationId: { in: ids } },
58	        orderBy: { createdAt: "desc" },
59	        distinct: ["conversationId"],
60	        select: { conversationId: true, body: true, sender: true },
61	      })
62	    : [];
63	  const lastBy = new Map(lasts.map((m) => [m.conversationId, m]));
64	
65	  const conversations = rows.map((r) => {
66	    const first = r.messages[0]?.body?.trim() || "";
67	    const last = lastBy.get(r.id);
68	    const title = first ? first.slice(0, 60) : "New conversation";
69	    const preview = last?.body?.trim()
70	      ? `${last.sender === "visitor" ? "You: " : ""}${last.body.trim().slice(0, 80)}`
71	      : "";
72	    return {
73	      id: r.id,
74	      title,
75	      preview,
76	      status: r.status,
77	      unread: r.unreadForUser,
78	      lastMessageAt: r.lastMessageAt.toISOString(),
79	    };
80	  });
81	
82	  return NextResponse.json({ conversations }, { headers: NO_STORE_HEADERS });
83	}
