9	/**
10	 * POST /api/chat/typing — a lightweight "the visitor is typing" ping from
11	 * <ChatWidget/>. Deliberately separate from POST /api/chat so typing pings never
12	 * consume the message-send rate budget. The agent sees the signal via
13	 * `listConversations` (lib/actions-chat.ts). Everything is best-effort: any
14	 * problem returns 204 and the indicator simply doesn't show.
15	 *
16	 * The signal is transient and self-expiring (lib/chat-typing.ts) — no DB write.
17	 */
18	export async function POST(req: Request) {
19	  // Generous cap: the client pings at most ~once every 2.5s while typing.
20	  const rl = checkRateLimit(`chat-typing:${trustedClientIp(req)}`, { max: 40, windowMs: 60_000 });
21	  if (!rl.ok) return new NextResponse(null, { status: 204 });
22	
23	  const raw = (await req.json().catch(() => ({}))) as Record<string, unknown>;
24	  const visitorId = typeof raw.visitorId === "string" ? raw.visitorId.trim().slice(0, 100) : "";
25	  if (!visitorId) return new NextResponse(null, { status: 204 });
26	
27	  const convo = await db.chatConversation
28	    .findFirst({
29	      where: { visitorId, status: "OPEN" },
30	      orderBy: { lastMessageAt: "desc" },
31	      select: { id: true },
32	    })
33	    .catch(() => null);
34	
35	  if (convo) markTyping(convo.id, "visitor");
36	  return new NextResponse(null, { status: 204 });
37	}
