8	/**
9	 * GET /api/tickets/attachment/[id] — stream a ticket-message attachment ONLY
10	 * to an authorized viewer: any staff member (SUPPORT/ADMIN), or the customer
11	 * who owns the ticket the message belongs to. Mirrors the authorization model
12	 * and response hardening of app/api/chat/attachment/[id]/route.ts.
13	 *
14	 * `id` is the TicketMessage id (a database id, never a filename — no path
15	 * traversal). Images are served inline for preview; every other allowed type
16	 * (PDF/TXT/ZIP) is served as a download so nothing can render as a document in
17	 * the browsing context regardless of what a mislabeled file claims to be.
18	 */
19	export async function GET(req: Request, { params }: { params: Promise<{ id: string }> }) {
20	  const { id } = await params;
21	  if (typeof id !== "string" || !id) return new Response("Not found", { status: 404 });
22	
23	  const message = await db.ticketMessage.findUnique({
24	    where: { id },
25	    select: {
26	      attachmentData: true,
27	      attachmentMime: true,
28	      attachmentName: true,
29	      ticket: { select: { userId: true } },
30	    },
31	  });
32	  if (!message || !message.attachmentData || !message.attachmentMime) {
33	    return new Response("Not found", { status: 404 });
34	  }
35	
36	  const user = await currentUser();
37	  const authorized = !!user && (isStaff(user.role) || user.id === message.ticket.userId);
38	  if (!authorized) return new Response("Forbidden", { status: 403 });
39	
40	  const mime = message.attachmentMime;
41	  const isImage = isImageMime(mime);
42	  const data: Buffer = Buffer.isBuffer(message.attachmentData)
43	    ? message.attachmentData
44	    : Buffer.from(message.attachmentData as Uint8Array);
45	
46	  const safeName = (message.attachmentName ?? "attachment").replace(/["\r\n]/g, "");
47	  const disposition = isImage ? `inline; filename="${safeName}"` : `attachment; filename="${safeName}"`;
48	
49	  return new Response(new Uint8Array(data), {
50	    status: 200,
51	    headers: {
52	      "Content-Type": mime,
53	      "Content-Length": String(data.length),
54	      "Content-Disposition": disposition,
55	      "X-Content-Type-Options": "nosniff",
56	      "Content-Security-Policy": "default-src 'none'; sandbox",
57	      "Cache-Control": "private, max-age=86400, no-transform",
58	    },
59	  });
60	}
