73	/** The TLS servername the mail server's certificate is issued for. */
74	export const MAIL_TLS_SERVERNAME = process.env.MAIL_TLS_SERVERNAME || "mail.nxeon.cloud";
75	
76	/**
77	 * TLS options for every webmail connection to the mail server (IMAP 993 and
78	 * SMTP submission 587). Shared so the two cannot drift apart.
79	 *
80	 * WHY VERIFICATION IS ON. We connect by internal IP (10.20.0.10) while the
81	 * server presents a public certificate for `mail.nxeon.cloud`, so a bare
82	 * connection fails on the name mismatch. The previous code resolved that by
83	 * setting `rejectUnauthorized: false` — which does not just tolerate the name
84	 * mismatch, it accepts ANY certificate from anything answering on that address.
85	 * The very first thing sent over that session is the customer's mailbox password
86	 * (IMAP LOGIN / SMTP AUTH), so anyone able to answer on the NAT bridge could
87	 * have harvested every mailbox credential on the platform, and nothing would
88	 * have looked wrong. `servername` alone is the correct fix: it sets SNI *and*
89	 * the name validation is performed against, so the real certificate verifies.
90	 *
91	 * MEASURED, not assumed (2026-07-27, from the app host):
92	 *   openssl s_client -connect 10.20.0.10:993 -servername mail.nxeon.cloud \
93	 *     -verify_return_error   ->  CN=mail.nxeon.cloud, "Verification: OK"
94	 *   …and the same on :587 with -starttls smtp.
95	 *
96	 * `MAIL_TLS_INSECURE=1` is a documented break-glass for an operator whose
97	 * certificate has genuinely expired mid-incident: it restores the old behaviour
98	 * from `.env` without a code change. It defaults OFF, so the safe state is the
99	 * one you get by doing nothing — the opposite of what it replaces.
100	 */
101	export function mailTlsOptions(): { servername: string; rejectUnauthorized: boolean } {
102	  return {
103	    servername: MAIL_TLS_SERVERNAME,
104	    rejectUnauthorized: process.env.MAIL_TLS_INSECURE !== "1",
105	  };
106	}
