138	/**
139	 * Adopt mailboxes that exist on Mailcow but have no local `Mailbox` row.
140	 *
141	 * WHY: `resolveMailbox` read ONLY `db.mailbox`, so a mailbox created directly on
142	 * the mail server — or one whose row was lost — was invisible in the portal even
143	 * though real mail was landing in it ("its not detecting the mailbox that i
144	 * already have on this account"). This reconciles the two.
145	 *
146	 * OWNERSHIP GUARD — the whole point of this function is that it MUST NOT become
147	 * a way to acquire someone else's mailbox:
148	 *   1. Only domains on a non-cancelled subscription owned by THIS user are read.
149	 *   2. Only subscriptions with `verified === true` are eligible. Owning a
150	 *      subscription ROW is not proof of owning the DOMAIN — an unverified
151	 *      external subscription is just a claim, and adopting on a claim would
152	 *      re-open the cross-tenant takeover fixed on 2026-07-25 by a side door.
153	 *   3. `Mailbox.address` is globally `@unique`, and we skip any address that
154	 *      already has a row, so a mailbox another tenant legitimately holds is
155	 *      never re-pointed at this user.
156	 *   4. `passwordEnc` is left NULL. We never learn the existing password, so the
157	 *      customer is told to reset it — adoption grants visibility, not access.
158	 *
159	 * Never throws: a Mailcow outage must not turn the mail page into an error.
160	 * Returns the number of rows created.
161	 */
162	export async function discoverMailboxes(userId: string): Promise<number> {
163	  if (!mailcowConfigured()) return 0;
164	
165	  // Guard against hammering Mailcow: the mail page calls this on every load for
166	  // an account with no mailbox, which is exactly the account that reaches here.
167	  const gate = checkRateLimit(`mail:discover:${userId}`, { max: 1, windowMs: 30_000 });
168	  if (!gate.ok) return 0;
169	
170	  const subs = await db.emailSubscription.findMany({
171	    where: { userId, status: { not: "CANCELLED" }, verified: true },
172	    select: { id: true, domainName: true },
173	  });
174	  if (subs.length === 0) return 0;
175	
176	  let created = 0;
177	  for (const sub of subs) {
178	    const domain = sub.domainName.trim().toLowerCase();
179	    if (!domain) continue;
180	
181	    let remote: Awaited<ReturnType<typeof mcListMailboxes>>;
182	    try {
183	      remote = await mcListMailboxes(domain);
184	    } catch (e) {
185	      console.warn(`[mailcow] discovery for ${domain} failed:`, e);
186	      continue;
187	    }
188	    if (remote.length === 0) continue;
189	
190	    const existing = await db.mailbox.findMany({
191	      where: { address: { in: remote.map((m) => m.address) } },
192	      select: { address: true },
193	    });
194	    const known = new Set(existing.map((m) => m.address.toLowerCase()));
195	
196	    for (const m of remote) {
197	      if (known.has(m.address)) continue;
198	      try {
199	        await db.mailbox.create({
200	          data: {
201	            subscriptionId: sub.id,
202	            address: m.address,
203	            quotaMB: m.quotaBytes > 0 ? Math.round(m.quotaBytes / (1024 * 1024)) : null,
204	            status: m.active ? "ACTIVE" : "SUSPENDED",
205	            displayName: m.name && m.name !== m.address ? m.name : null,
206	          },
207	        });
208	        created++;
209	      } catch {
210	        // Unique-violation race (two tabs discovering at once) — the row exists
211	        // now either way, which is the outcome we wanted.
212	      }
213	    }
214	  }
215	
216	  if (created > 0) {
217	    await db.auditLog
218	      .create({ data: { userId, action: "mailbox.discover", detail: `adopted ${created} from mail server` } })
219	      .catch(() => {});
220	  }
221	  return created;
222	}
