224	/**
225	 * Why the caller can't open webmail, so the UI can say what is actually wrong
226	 * instead of one catch-all "No mailbox connected".
227	 */
228	export type MailAccessState =
229	  | { kind: "ok"; address: string }
230	  | { kind: "no-subscription" }
231	  | { kind: "unverified-domain"; domains: string[] }
232	  | { kind: "no-mailbox"; domains: string[] }
233	  | { kind: "no-password"; address: string }
234	  | { kind: "server-unreachable"; address: string };
