236	/**
237	 * Diagnose mail access for a user. Runs Mailcow discovery first so a mailbox
238	 * that only exists on the server is found before we declare there is none.
239	 */
240	export async function mailAccessState(userId: string): Promise<MailAccessState> {
241	  await discoverMailboxes(userId).catch(() => 0);
242	
243	  const subs = await db.emailSubscription.findMany({
244	    where: { userId, status: { not: "CANCELLED" } },
245	    select: { domainName: true, verified: true, external: true },
246	  });
247	  if (subs.length === 0) return { kind: "no-subscription" };
248	
249	  const boxes = await db.mailbox.findMany({
250	    where: { subscription: { userId } },
251	    orderBy: { createdAt: "asc" },
252	    select: { address: true, passwordEnc: true },
253	  });
254	
255	  if (boxes.length === 0) {
256	    const unverified = subs.filter((s) => !s.verified).map((s) => s.domainName);
257	    const verified = subs.filter((s) => s.verified).map((s) => s.domainName);
258	    // An unverified domain is the more actionable problem: no mailbox can even
259	    // be created on it yet, so lead with that.
260	    if (verified.length === 0) return { kind: "unverified-domain", domains: unverified };
261	    return { kind: "no-mailbox", domains: verified };
262	  }
263	
264	  const withPassword = boxes.find((b) => decryptSecret(b.passwordEnc));
265	  if (!withPassword) return { kind: "no-password", address: boxes[0].address };
266	
267	  // A mailbox and a credential exist, so the page's failure was the mail server
268	  // itself (IMAP down, auth rejected, TLS problem) — not missing setup.
269	  return { kind: "server-unreachable", address: withPassword.address };
270	}
