272	/**
273	 * Resolve the mailbox a request may act on. Requires an authenticated user,
274	 * loads only mailboxes belonging to that user's email subscriptions, and (when
275	 * `mailboxAddress` is given) verifies it is one of them. Decrypts the stored
276	 * credential; throws a friendly error if the password was never captured.
277	 *
278	 * NEVER returns a mailbox the caller does not own.
279	 */
280	export async function resolveMailbox(mailboxAddress?: string): Promise<ResolvedMailbox> {
281	  const user = await requireUser();
282	
283	  // --- Staff-only: read COMPANY mailboxes (admin@, support@, …) in-portal. ---
284	  // This is an ADDITIVE branch: it only runs for staff, so the customer
285	  // resolution below is completely unchanged. A company mailbox is synthesized
286	  // into the same ResolvedMailbox shape (no EmailSubscription backing it).
287	  // Also additive for a granted EMPLOYEE — this is the REAL data-layer
288	  // authority every mail action (listFolders/listMessages/sendMessage/etc. in
289	  // lib/actions-mail.ts) goes through, so the companyInbox grant must reach
290	  // HERE, not just the /admin/inbox or /staff/inbox page — see
291	  // lib/staff-grants.ts's doc comment on the lib/team-guard.ts lesson.
292	  if (isStaff(user.role) || (user.role === "EMPLOYEE" && (await hasAreaAccess(user, "companyInbox")))) {
293	    const wantedLc = mailboxAddress?.trim().toLowerCase();
294	    const synthesize = (c: {
295	      id: string;
296	      address: string;
297	      label: string | null;
298	      passwordEnc: string;
299	      quotaMB: number;
300	      status: string;
301	    }): ResolvedMailbox => {
302	      const password = decryptSecret(c.passwordEnc);
303	      if (!password) throw new Error("Reset this mailbox's password to enable webmail access.");
304	      return {
305	        user,
306	        mailboxId: `company:${c.id}`,
307	        address: c.address,
308	        quotaMB: c.quotaMB,
309	        cred: { address: c.address, password },
310	        identity: { displayName: c.label, replyTo: null, organization: null },
311	        subscription: {
312	          id: `company:${c.id}`,
313	          domainName: COMPANY_MAIL_DOMAIN,
314	          external: false,
315	          verified: true,
316	          status: c.status,
317	        },
318	      };
319	    };
320	    // Only resolve an EXPLICITLY requested company address (the admin inbox always
321	    // passes one). With no address, fall through to the customer path — so a
322	    // staffer's own /dashboard/mail never silently lands on a company mailbox.
323	    if (wantedLc) {
324	      const c = await db.companyMailbox.findUnique({ where: { address: wantedLc } });
325	      // canAccessMailbox is "all" for SUPPORT/BILLING/ADMIN (isStaff — unchanged),
326	      // and scoped to their own + specifically granted addresses for EMPLOYEE
327	      // (see lib/staff-mailbox-access.ts). This is the actual enforcement point:
328	      // treating a mailbox this employee can't access as "not found" is what
329	      // makes companyInbox mean "the inbox feature is reachable," not "read
330	      // every company mailbox" — confirmed live 2026-09-03 it meant the latter.
331	      if (c && (await canAccessMailbox(user, c.address))) return synthesize(c);
332	      // Not a company address, or not one this user may access — fall through
333	      // to the customer path below (never distinguishes the two to the caller).
334	    }
335	  }
336	
337	  const load = () =>
338	    db.mailbox.findMany({
339	      where: { subscription: { userId: user.id } },
340	      include: { subscription: true },
341	      orderBy: { createdAt: "asc" },
342	    });
343	
344	  let boxes = await load();
345	  const wanted = mailboxAddress?.trim().toLowerCase();
346	
347	  // A miss here used to be terminal, which is how a mailbox that exists on the
348	  // mail server but has no local row became "you do not have a mailbox yet".
349	  // Reconcile against Mailcow (verified domains only) before giving that answer.
350	  if (boxes.length === 0 || (wanted && !boxes.some((b) => b.address.toLowerCase() === wanted))) {
351	    if (await discoverMailboxes(user.id).catch(() => 0)) boxes = await load();
352	  }
353	
354	  if (boxes.length === 0) {
355	    throw new Error("You do not have a mailbox yet. Add an email plan to use webmail.");
356	  }
357	
358	  let box = boxes[0];
359	  if (wanted) {
360	    const match = boxes.find((b) => b.address.toLowerCase() === wanted);
361	    if (!match) throw new Error("You do not have access to that mailbox.");
362	    box = match;
363	  }
364	
365	  const password = decryptSecret(box.passwordEnc);
366	  if (!password) {
367	    throw new Error("Please reset your mailbox password first to enable webmail access.");
368	  }
369	
370	  return {
371	    user,
372	    mailboxId: box.id,
373	    address: box.address,
374	    quotaMB: box.quotaMB ?? null,
375	    cred: { address: box.address, password },
376	    identity: {
377	      displayName: box.displayName,
378	      replyTo: box.replyTo,
379	      organization: box.organization,
380	    },
381	    subscription: {
382	      id: box.subscription.id,
383	      domainName: box.subscription.domainName,
384	      external: box.subscription.external,
385	      verified: box.subscription.verified,
386	      status: box.subscription.status,
387	    },
388	  };
389	}
