391	/** Build a per-request imapflow client for the given credential. */
392	export function createImapClient(cred: MailboxCredentials): ImapFlow {
393	  return new ImapFlow({
394	    host: MAIL_IMAP_HOST,
395	    port: MAIL_IMAP_PORT,
396	    secure: true,
397	    // We connect by internal IP but the cert is for mail.nxeon.cloud — set SNI
398	    // and validation servername so TLS verifies against the right name.
399	    servername: MAIL_TLS_SERVERNAME,
400	    tls: mailTlsOptions(),
401	    auth: { user: cred.address, pass: cred.password },
402	    logger: false,
403	    disableAutoIdle: true,
404	    // ImapFlow's default connectionTimeout is 90s — measured live against
405	    // this exact mail server (2026-08-29): a single struggling connection
406	    // attempt genuinely took the full 90s to fail. app/admin/inbox/page.tsx
407	    // tries EACH company mailbox in sequence on a bad first pick, so with 5
408	    // mailboxes a single slow one could hang the whole admin inbox page for
409	    // several minutes. This host also shows real CPU pressure-stall metrics
410	    // (contention from an overcommitted physical node, not a Mailcow config
411	    // bug), so occasional slow connects are expected — 10s is generous for a
412	    // LAN hop but fails far faster than 90s when the server genuinely can't
413	    // respond. socketTimeout stays closer to the library default since it
414	    // covers in-progress operations (fetching messages), which can
415	    // legitimately take longer than a bare connect.
416	    connectionTimeout: 10_000,
417	    greetingTimeout: 8_000,
418	    socketTimeout: 30_000,
419	  });
420	}
