422	/**
423	 * Open a short-lived IMAP connection, run `fn`, and ALWAYS close it (graceful
424	 * logout, falling back to a hard close). Suitable for one operation per request.
425	 */
426	export async function withImap<T>(cred: MailboxCredentials, fn: (client: ImapFlow) => Promise<T>): Promise<T> {
427	  const client = createImapClient(cred);
428	  await client.connect();
429	  try {
430	    return await fn(client);
431	  } finally {
432	    try {
433	      await client.logout();
434	    } catch {
435	      try {
436	        client.close();
437	      } catch {
438	        /* already gone */
439	      }
440	    }
441	  }
442	}
