444	/**
445	 * Like `withImap` but also selects `path` under a mailbox lock (released before
446	 * the connection closes). Use for any op that fetches/searches/mutates messages.
447	 */
448	export async function withMailbox<T>(
449	  cred: MailboxCredentials,
450	  path: string,
451	  fn: (client: ImapFlow) => Promise<T>,
452	  opts?: { readOnly?: boolean },
453	): Promise<T> {
454	  return withImap(cred, async (client) => {
455	    const lockOpts: MailboxLockOptions = { readOnly: opts?.readOnly };
456	    const lock = await client.getMailboxLock(path, lockOpts);
457	    try {
458	      return await fn(client);
459	    } finally {
460	      lock.release();
461	    }
462	  });
463	}
