465	/** Map an IMAP special-use flag / folder name to our MailFolderRole. */
466	export function folderRole(path: string, specialUse?: string): MailFolderRole {
467	  const su = (specialUse || "").toLowerCase();
468	  if (su === "\\inbox" || path.toUpperCase() === "INBOX") return "inbox";
469	  switch (su) {
470	    case "\\sent":
471	      return "sent";
472	    case "\\drafts":
473	      return "drafts";
474	    case "\\trash":
475	      return "trash";
476	    case "\\junk":
477	      return "junk";
478	    case "\\archive":
479	    case "\\all":
480	      return "archive";
481	  }
482	  // Fall back to common folder names for servers that don't advertise SPECIAL-USE.
483	  const leaf = (path.split(/[/.]/).pop() || path).toLowerCase();
484	  if (leaf === "inbox") return "inbox";
485	  if (["sent", "sent items", "sent mail", "sent messages"].includes(leaf)) return "sent";
486	  if (["drafts", "draft"].includes(leaf)) return "drafts";
487	  if (["trash", "deleted", "deleted items", "deleted messages", "bin"].includes(leaf)) return "trash";
488	  if (["junk", "spam", "junk email", "junk e-mail"].includes(leaf)) return "junk";
489	  if (["archive", "archives", "all mail", "all"].includes(leaf)) return "archive";
490	  return "custom";
491	}
