503	/**
504	 * Walk a BODYSTRUCTURE tree and return the IMAP part id of the best text part
505	 * to preview: prefers text/plain, then text/html, then the first leaf. Returns
506	 * "1" for a simple single-part message (whose structure carries no part id).
507	 */
508	export function findPreviewPart(structure: MessageStructureObject | undefined): { part: string; isHtml: boolean } {
509	  if (!structure) return { part: "1", isHtml: false };
510	  const leaves: MessageStructureObject[] = [];
511	  const walk = (node: MessageStructureObject) => {
512	    if (node.childNodes && node.childNodes.length) {
513	      node.childNodes.forEach(walk);
514	    } else {
515	      leaves.push(node);
516	    }
517	  };
518	  walk(structure);
519	
520	  const isBody = (n: MessageStructureObject) => (n.disposition || "").toLowerCase() !== "attachment";
521	  const plain = leaves.find((n) => (n.type || "").toLowerCase() === "text/plain" && isBody(n));
522	  if (plain) return { part: plain.part || "1", isHtml: false };
523	  const html = leaves.find((n) => (n.type || "").toLowerCase() === "text/html" && isBody(n));
524	  if (html) return { part: html.part || "1", isHtml: true };
525	  return { part: leaves[0]?.part || "1", isHtml: (leaves[0]?.type || "").toLowerCase() === "text/html" };
526	}
527	
528	/** True if a BODYSTRUCTURE tree contains at least one attachment-like part. */
529	export function structureHasAttachments(structure: MessageStructureObject | undefined): boolean {
530	  if (!structure) return false;
531	  let found = false;
532	  const walk = (node: MessageStructureObject) => {
533	    const type = (node.type || "").toLowerCase();
534	    const disp = (node.disposition || "").toLowerCase();
535	    if (node.childNodes && node.childNodes.length) {
536	      node.childNodes.forEach(walk);
537	      return;
538	    }
539	    if (disp === "attachment") found = true;
540	    else if (!type.startsWith("text/") && !type.startsWith("multipart/")) found = true;
541	  };
542	  walk(structure);
543	  return found;
544	}
