546	/** Read imapflow message flags into the summary booleans. */
547	export function readFlags(flags: Set<string> | undefined): { seen: boolean; flagged: boolean; answered: boolean } {
548	  const f = flags ?? new Set<string>();
549	  return { seen: f.has("\\Seen"), flagged: f.has("\\Flagged"), answered: f.has("\\Answered") };
550	}
